INSERT INTO `goods` VALUES (2527, 1, 1, '郑板桥款墨竹写意国画', '/uploads/collect/2793/50e505e37941f8c1.jpg', '[\"/uploads/collect/2793/50e505e37941f8c1.jpg\",\"/uploads/collect/2793/c50fe6ec90ca749b.jpg\",\"/uploads/collect/2793/dc1a9ff3f7d6d139.jpg\",\"/uploads/collect/2793/1d1917e32f1373dc.jpg\"]', '<h3><strong>藏品评价</strong></h3><p class=\"marklang-paragraph\">这幅墨竹作品笔墨舒展流畅，竹竿中锋行笔圆浑劲挺，竹叶以行草笔意写出，组合排布疏密得当，墨色浓淡过渡自然柔和，把郑板桥画竹“瘦劲孤高、豪气凌云”的艺术特质表现得十分到位，题款书法延续了板桥体错落灵动的风格，诗文内容与画面意境高度契合，整体品相保存完好，纸面仅留下自然的岁月折痕，没有出现严重的破损、脱墨问题，作为兼具文人意趣与装饰属性的国画作品，既可以悬挂于书房厅堂烘托清雅的中式氛围，也是民间书画收藏里受众极广的经典题材藏品，兼具观赏把玩价值与民俗文化纪念意义。</p><p><br>&nbsp;</p>', 380000.00, 3800.00, 0.00, 38000.00, 0.00, 0.00, 0, 0, 1788642850, 1788783833, 0, 3, '', 26103, 0, 0.00, 0, 0, 1788642850, 1788940859);
