CREATE TABLE `balance_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '类型:recharge充值 deposit保证金 pay支付 income收入 refund退回 withdraw提现 reward奖励',
  `amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '变动金额(正入负出)',
  `balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后可用余额',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_type`(`type`) USING BTREE,
  INDEX `idx_user_id_amount`(`user_id`, `id`, `amount`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '余额流水表' ROW_FORMAT = DYNAMIC;

