  `is_winner` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否得标 1是',
  `create_time` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user`(`user_id`) USING BTREE,
  INDEX `idx_goods_status_price`(`goods_id`, `status`, `price`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '出价记录表' ROW_FORMAT = DYNAMIC;

