-- ----------------------------
-- Table structure for order
-- ----------------------------
DROP TABLE IF EXISTS `order`;
CREATE TABLE `order`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `goods_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `goods_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品标题',
  `goods_cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品封面',
  `seller_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '卖家ID',
  `buyer_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '买家ID',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '成交价',
  `commission_rate` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '佣金比例%',
  `commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '佣金金额',
  `seller_income` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '卖家实收',
  `deposit` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '买家保证金',
  `pay_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '支付状态 0未支付 1已支付',
  `pay_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付时间',
  `order_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0待付款 1待发货 2待收货 3已完成 4已取消',
  `ship_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人',
  `ship_mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货电话',
  `ship_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `ship_company` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递公司',
  `ship_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递单号',
  `ship_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货时间',
  `finish_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '完成时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `update_time` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no`) USING BTREE,
  INDEX `idx_goods`(`goods_id`) USING BTREE,
  INDEX `idx_buyer_status`(`buyer_id`, `order_status`) USING BTREE,
  INDEX `idx_seller_status`(`seller_id`, `order_status`) USING BTREE,
  INDEX `idx_pay_order_create`(`pay_status`, `order_status`, `create_time`) USING BTREE,
  INDEX `idx_status_paytime`(`order_status`, `pay_time`) USING BTREE,
  INDEX `idx_paystatus_paytime`(`pay_status`, `pay_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '拍卖订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of order
